            self.power_ups.append(PowerUp(power_up_type, Position(x, y), time.time()))

        # Spawn new hazards occasionally
        if random.random() < Hazard_SPWN_RATE and len(self.hazards) < 8:
            x = random.uniform(10, MAP_WIDTH - 10)
            y = random.uniform(10, MAP_HEIGHT - 10)
            hazard_type = random.choice(list(HazardType))
            self.hazards.append(Hazard(hazard_type, Position(x, y), time.time()))

        # Update team scores based on objective completion
        self.update_team_scores()

