        self.adapt_difficulty()

    def update_team_scores(self):
        # Clear previous scores
        for team in range(TEAM_COUNT):
            self.team_scores[team] = 0

        # Add scores based on objective completion
        for obj in self.objectives:
            if obj.is_captured:
                # Score is based on completion percentage and time
                score = obj.completion_percentage * 0.5
                # Give to the team that captured it
                self.team_scores[obj.team_id] += score

        # Add scores based on robot kills and survival
        for robot in self.robots:
            if robot.is_alive:
                # Team gets points for alive robots
                self.team_scores[robot.team] += 1
                # Team gets points for robot's accumulated score
                self.team_scores[robot.team] += robot.get_score(self) * 0.1

    def adapt_difficulty(self):
        """Adaptive difficulty system"""
        # Calculate average team performance
        avg_score = sum(self.team_scores.values()) / TEAM_COUNT if TEAM_COUNT > 0 else 0
        score_variance = abs(self.team_scores[0] - self.team_scores[1])

        # If one team is dominating too much, increase difficulty for them
        if score_variance > 50:
            # Increase difficulty for the leading team
            leading_team = 0 if self.team_scores[0] > self.team_scores[1] else 1
            other_team = 1 - leading_team

            # Adjust difficulty for leading team's AI
            if self.difficulty < 0.9:
                self.difficulty += 0.02
            # Make other team's AI slightly easier to balance
            if self.difficulty > 0.1:
                self.difficulty -= 0.01
        else:
            # If scores are balanced, maintain current difficulty
            if self.difficulty > 0.4 and self.difficulty < 0.6:
                pass
            elif self.difficulty < 0.4:
                self.difficulty += 0.01
            else:
                self.difficulty -= 0.01

        # Ensure difficulty stays within bounds
        self.difficulty = max(0.1, min(0.9, self.difficulty))


