# CyberArena - Multi-Agent Battle Arena Simulation
# A futuristic team-based robot combat simulation with adaptive AI, dynamic objectives, and immersive feedback

import random
import time
import math
import heapq
import json
import threading
from enum import Enum
from dataclasses import dataclass, field
from typing import List, Dict, Set, Optional, Tuple, Any
from collections import defaultdict, deque
import pygame
import pygame.mixer
import numpy as np

# ----------------------------
# Configuration and Constants
# ----------------------------

# Game constants
GRID_SIZE = 100
MAP_WIDTH = 50
MAP_HEIGHT = 50
FPS = 60
TEAM_COUNT = 2
MAX_ROBOTS_PER_TEAM = 5
MAX_BATTLES = 100
POWER_UP_SPAWN_RATE = 0.02
Hazard_SPWN_RATE = 0.01

# Weapon types
class WeaponType(Enum):
    LASER_RIFLE = "laser_rifle"
    PLASMA_CANNON = "plasma_cannon"
    SHOTGUN = "shotgun"
    MELEE_BLADE = "melee_blade"
    SNIPER_RIFLE = "sniper_rifle"
    FLAMETHROWER = "flamethrower"

# Team roles
class Role(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SUPPORT = "support"
    SCOUT = "scout"
    CONTROLLER = "controller"

# Objective types
class ObjectiveType(Enum):
    CAPTURE_FLAG = "capture_flag"
    DEFEND_BASE = "defend_base"
    ESCORT_PAYLOAD = "escort_payload"
    DOMINATE_ZONE = "dominate_zone"

# Power-up types
class PowerUpType(Enum):
    HEALTH_PACK = "health_pack"
    SHIELD_BOOST = "shield_boost"
    SPEED_BOOST = "speed_boost"
    DAMAGE_BOOST = "damage_boost"
    CLONE = "clone"
    TELEPORT = "teleport"

# Hazard types
class HazardType(Enum):
    ELECTRIC_FIELD = "electric_field"
    FLAMING_OIL = "flaming_oil"
    GRAVITY_WELL = "gravity_well"
    MINEFIELD = "minefield"
    SILENCE_FIELD = "silence_field"

# ----------------------------
# Data Structures
# ----------------------------

@dataclass
class Position:
    x: float
    y: float

    def distance_to(self, other: 'Position') -> float:
        return math.sqrt((self.x - other.x)**2 + (self.y - other.y)**2)

    def __add__(self, other: 'Position') -> 'Position':
        return Position(self.x + other.x, self.y + other.y)

    def __sub__(self, other: 'Position') -> 'Position':
        return Position(self.x - other.x, self.y - other.y)

    def normalize(self) -> 'Position':
        mag = math.sqrt(self.x**2 + self.y**2)
        if mag == 0:
            return Position(0, 0)
        return Position(self.x / mag, self.y / mag)

@dataclass
class Weapon:
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    cooldown: float = 0.0
    is_melee: bool = False

    def can_fire(self) -> bool:
        return self.cooldown <= 0 and self.ammo > 0

    def fire(self) -> bool:
        if self.can_fire():
            self.ammo -= 1
            self.cooldown = self.fire_rate
            return True
        return False

    def update(self, delta_time: float):
        if self.cooldown > 0:
            self.cooldown -= delta_time
        if self.ammo < self.max_ammo:
            self.ammo = min(self.max_ammo, self.ammo + 0.1 * delta_time)  # Recharge slowly

@dataclass
class Robot:
    id: int
    team: int
    position: Position
    velocity: Position = field(default_factory=lambda: Position(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    shield: float = 0.0
    max_shield: float = 50.0
    speed: float = 3.0
    rotation: float = 0.0  # radians
    role: Role = Role.ATTACKER
    weapon: Weapon = None
    weapons: List[Weapon] = field(default_factory=list)
    is_alive: bool = True
    last_action: str = ""
    knowledge_base: Dict = field(default_factory=dict)
    strategy_memory: List[Dict] = field(default_factory=list)
    last_seen_enemies: List[int] = field(default_factory=list)
    objectives: Set[ObjectiveType] = field(default_factory=set)
    power_ups: List[PowerUpType] = field(default_factory=list)
    is_vulnerable: bool = False
    vulnerability_duration: float = 0.0
    spawn_time: float = 0.0
    last_update_time: float = 0.0

    def __post_init__(self):
        if not self.weapon:
            self.weapon = Weapon(WeaponType.LASER_RIFLE, 15, 100, 0.5, 30, 30)
        self.weapons.append(self.weapon)
        self.spawn_time = time.time()
        self.last_update_time = self.spawn_time

    def update(self, delta_time: float, environment: 'Environment'):
        if not self.is_alive:
            return

        # Update weapon cooldowns
        for weapon in self.weapons:
            weapon.update(delta_time)

        # Update vulnerability timer
        if self.is_vulnerable:
            self.vulnerability_duration -= delta_time
            if self.vulnerability_duration <= 0:
                self.is_vulnerable = False

        # Update position based on velocity
        self.position.x += self.velocity.x * delta_time * self.speed
        self.position.y += self.velocity.y * delta_time * self.speed

        # Keep robot within bounds
        self.position.x = max(0, min(MAP_WIDTH, self.position.x))
        self.position.y = max(0, min(MAP_HEIGHT, self.position.y))

        # Update last update time
        self.last_update_time = time.time()

        # Check for environmental hazards
        self.check_hazard_interaction(environment)

    def take_damage(self, damage: float, source_robot_id: int = None):
        if not self.is_alive:
            return

        # Apply shield reduction first
        if self.shield > 0:
            shield_absorbed = min(damage, self.shield)
            self.shield -= shield_absorbed
            damage -= shield_absorbed

        # Apply health reduction
        if damage > 0:
            self.health -= damage
            if self.health <= 0:
                self.health = 0
                self.is_alive = False
                # Trigger death effects
                self.last_action = f"deceased_by_{source_robot_id}" if source_robot_id else "deceased"

    def heal(self, amount: float):
        if not self.is_alive:
            return
        self.health = min(self.max_health, self.health + amount)

    def add_shield(self, amount: float):
        if not self.is_alive:
            return
        self.shield = min(self.max_shield, self.shield + amount)

    def add_power_up(self, power_up: PowerUpType):
        self.power_ups.append(power_up)
        # Apply power-up effects immediately
        self.apply_power_up(power_up)

    def apply_power_up(self, power_up: PowerUpType):
        if power_up == PowerUpType.HEALTH_PACK:
            self.heal(30)
        elif power_up == PowerUpType.SHIELD_BOOST:
            self.add_shield(25)
        elif power_up == PowerUpType.SPEED_BOOST:
            self.speed *= 1.5
            # Reset after 10 seconds
            threading.Timer(10.0, self.reset_speed).start()
        elif power_up == PowerUpType.DAMAGE_BOOST:
            for weapon in self.weapons:
                weapon.damage *= 1.5
            # Reset after 15 seconds
            threading.Timer(15.0, self.reset_damage).start()
        elif power_up == PowerUpType.CLONE:
            # In a real implementation, this would spawn a clone
            pass
        elif power_up == PowerUpType.TELEPORT:
            # Teleport to a random safe location
            safe_pos = self.find_safe_teleport_location()
            if safe_pos:
                self.position = safe_pos

    def reset_speed(self):
        self.speed /= 1.5

    def reset_damage(self):
        for weapon in self.weapons:
            weapon.damage /= 1.5

    def find_safe_teleport_location(self) -> Optional[Position]:
        # Find a random location away from enemies and hazards
        for _ in range(10):
            x = random.uniform(0, MAP_WIDTH)
            y = random.uniform(0, MAP_HEIGHT)
            test_pos = Position(x, y)
            # Check distance from all robots
            safe = True
            for robot in self.knowledge_base.get('robots', []):
                if robot.is_alive and robot.team != self.team:
                    if test_pos.distance_to(robot.position) < 15:
                        safe = False
                        break
            if safe:
                return test_pos
        return None

    def check_hazard_interaction(self, environment: 'Environment'):
        # Check if robot is in a hazard zone
        for hazard in environment.hazards:
            if hazard.position.distance_to(self.position) < hazard.radius:
                if hazard.type == HazardType.ELECTRIC_FIELD:
                    self.take_damage(1.5)
                    self.is_vulnerable = True
                    self.vulnerability_duration = 2.0
                elif hazard.type == HazardType.FLAMING_OIL:
                    self.take_damage(2)
                    self.velocity = Position(self.velocity.x * 0.7, self.velocity.y * 0.7)  # Slow down
                elif hazard.type == HazardType.GRAVITY_WELL:
                    # Pull robot toward center
                    direction = hazard.position - self.position
                    if direction.x != 0 or direction.y != 0:
                        self.velocity += direction.normalize() * 0.5
                elif hazard.type == HazardType.MINEFIELD:
                    if random.random() < 0.3:  # 30% chance to trigger
                        self.take_damage(20)
                        self.velocity = Position(0, 0)  # Stop movement
                elif hazard.type == HazardType.SILENCE_FIELD:
                    # Disable robot's communication abilities temporarily
                    pass  # Would affect AI decision making in a real implementation

    def get_best_weapon(self, target_position: Position) -> Optional[Weapon]:
        """Select best weapon based on distance to target"""
        if not self.weapons:
            return None

        distance = self.position.distance_to(target_position)
        best_weapon = None
        best_score = -1

        for weapon in self.weapons:
            if weapon.ammo <= 0:
                continue

            score = 0
            # Range bonus
            if weapon.range >= distance:
                score += 10
            else:
                score -= 5

            # Damage bonus
            score += weapon.damage * 0.5

            # Fire rate bonus
            score += (1 / weapon.fire_rate) * 2

            # Melee bonus if close
            if weapon.is_melee and distance < 5:
                score += 20

            if score > best_score:
                best_score = score
                best_weapon = weapon

        return best_weapon

    def can_see_target(self, target_position: Position, environment: 'Environment') -> bool:
        """Check if target is visible (no obstacles between)"""
        # For simplicity, assume no obstacles in this simulation
        # In a full implementation, this would use raycasting
        return self.position.distance_to(target_position) < 150  # Line of sight limit

    def update_knowledge(self, environment: 'Environment'):
        """Update internal knowledge base with current environment state"""
        self.knowledge_base = {
            'robots': environment.robots,
            'power_ups': environment.power_ups,
            'hazards': environment.hazards,
            'objectives': environment.objectives,
            'map': environment.map_data,
            'time': time.time(),
            'team_members': [r for r in environment.robots if r.team == self.team and r.is_alive]
        }

        # Update last seen enemies
        self.last_seen_enemies = [
            r.id for r in environment.robots 
            if r.team != self.team and r.is_alive and self.position.distance_to(r.position) < 80
        ]

    def decide_action(self, environment: 'Environment', difficulty: float) -> str:
        """AI decision making system based on role, environment, and adaptive difficulty"""
        if not self.is_alive:
            return "dead"

        # Update knowledge
        self.update_knowledge(environment)

        # Determine current objective priority
        team_objectives = [obj for obj in environment.objectives if obj.team_id == self.team]
        target_objective = None
        if team_objectives:
            # Choose objective with lowest completion percentage or closest
            target_objective = min(team_objectives, key=lambda x: x.completion_percentage)

        # Use role-based strategy
        strategy = self.get_role_strategy(target_objective, environment, difficulty)

        # Memory-based learning
        if self.strategy_memory:
            # Occasionally deviate from learned patterns to explore
            if random.random() < 0.1 * (1 - difficulty):
                strategy = self.explore_new_strategy(environment)

        # Apply adaptive difficulty
        if difficulty > 0.7:
            # Hard AI: More aggressive, better coordination
            if random.random() < 0.3:
                strategy = self.make_aggressive_decision(environment)
        elif difficulty < 0.3:
            # Easy AI: More cautious, less coordination
            if random.random() < 0.4:
                strategy = self.make_cautious_decision(environment)

        self.last_action = strategy
        return strategy

    def get_role_strategy(self, target_objective, environment, difficulty) -> str:
        """Return a strategic action based on robot's role"""
        # Find nearest enemies and teammates
        enemies = [r for r in environment.robots if r.team != self.team and r.is_alive]
        teammates = [r for r in environment.robots if r.team == self.team and r.is_alive]

        # Get closest enemy
        closest_enemy = None
        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))

        # Get closest objective
        if target_objective:
            obj_pos = target_objective.position
            distance_to_obj = self.position.distance_to(obj_pos)

            # Role-specific behaviors
            if self.role == Role.ATTACKER:
                if closest_enemy and self.position.distance_to(closest_enemy.position) < 30:
                    return "attack_enemy"
                elif distance_to_obj < 25:
                    return "capture_objective"
                else:
                    return "move_to_objective"

            elif self.role == Role.DEFENDER:
                if closest_enemy and self.position.distance_to(closest_enemy.position) < 40:
                    return "attack_enemy"
                elif target_objective and distance_to_obj < 20:
                    return "defend_objective"
                else:
                    return "patrol_base"

            elif self.role == Role.SUPPORT:
                if teammates:
                    nearest_teammate = min(teammates, key=lambda t: self.position.distance_to(t.position))
                    if nearest_teammate.health < 50:
                        return "heal_teammate"
                    elif closest_enemy and self.position.distance_to(closest_enemy.position) < 50:
                        return "provide_cover"
                return "move_to_support_position"

            elif self.role == Role.SCOUT:
                if closest_enemy and self.position.distance_to(closest_enemy.position) < 60:
                    return "track_enemy"
                else:
                    return "explore_area"

            elif self.role == Role.CONTROLLER:
                if target_objective and distance_to_obj < 30:
                    return "control_objective"
                elif teammates:
                    return "coordinate_team"

        # Default strategy
        if closest_enemy and self.position.distance_to(closest_enemy.position) < 50:
            return "attack_enemy"
        elif target_objective and distance_to_obj < 40:
            return "move_to_objective"
        else:
            return "patrol"

    def make_aggressive_decision(self, environment) -> str:
        """Aggressive behavior pattern"""
        enemies = [r for r in environment.robots if r.team != self.team and r.is_alive]
        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
            if self.position.distance_to(closest_enemy.position) < 40:
                return "attack_enemy"
        return "move_to_enemy_base"

    def make_cautious_decision(self, environment) -> str:
        """Cautious behavior pattern"""
        enemies = [r for r in environment.robots if r.team != self.team and r.is_alive]
        if enemies:
            closest_enemy = min(enemies, key=lambda e: self.position.distance_to(e.position))
            if self.position.distance_to(closest_enemy.position) < 25:
                return "retreat"
        return "patrol_safe_zone"

    def explore_new_strategy(self, environment) -> str:
        """Randomly try a different strategy to learn"""
        strategies = [
            "attack_enemy", "move_to_objective", "defend_objective", 
            "heal_teammate", "provide_cover", "explore_area", "retreat"
        ]
        return random.choice(strategies)

    def move_toward(self, target: Position):
        """Move robot toward target position"""
        direction = target - self.position
        if direction.x != 0 or direction.y != 0:
            direction = direction.normalize()
            self.velocity = direction

