# solution.py
"""
CyberArena - A Multi-Agent System for Futuristic Robot Battle Arena

A dynamic, team-based combat simulation where AI-controlled robots compete
in strategic objectives with adaptive difficulty, learning capabilities,
and immersive audiovisual feedback.
"""

import random
import time
import math
import threading
import queue
from enum import Enum
from typing import List, Dict, Tuple, Optional, Any
from dataclasses import dataclass, field
from collections import defaultdict, deque
import pygame
import numpy as np


# ================================
# ENUMERATIONS AND DATA CLASSES
# ================================

class Team(Enum):
    RED = "red"
    BLUE = "blue"


class WeaponType(Enum):
    RANGED = "ranged"
    MELEE = "melee"
    EXPLOSIVE = "explosive"


class RobotRole(Enum):
    ATTACKER = "attacker"
    DEFENDER = "defender"
    SUPPORT = "support"
    SCOUT = "scout"


class ObjectiveType(Enum):
    FLAG_CAPTURE = "flag_capture"
    BASE_DEFENSE = "base_defense"
    PAYLOAD_ESCORT = "payload_escort"
    CONTROL_POINT = "control_point"


class PowerUpType(Enum):
    HEALTH_PACK = "health_pack"
    AMMO_RELOAD = "ammo_reload"
    SPEED_BOOST = "speed_boost"
    SHIELD = "shield"
    TELEPORT = "teleport"
    TIME_SLOW = "time_slow"


class HazardType(Enum):
    LAVA = "lava"
    ELECTRIC_FIELD = "electric_field"
    MINEFIELD = "minefield"
    GRAVITY_WELL = "gravity_well"


@dataclass
class Vector2D:
    """2D Vector for position, velocity, and direction"""
    x: float = 0.0
    y: float = 0.0

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def __truediv__(self, scalar):
        if scalar == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / scalar, self.y / scalar)

    def magnitude(self):
        return math.sqrt(self.x**2 + self.y**2)

    def normalize(self):
        mag = self.magnitude()
        if mag == 0:
            return Vector2D(0, 0)
        return self / mag

    def distance_to(self, other):
        return (self - other).magnitude()

    def copy(self):
        return Vector2D(self.x, self.y)


@dataclass
class Weapon:
    """Weapon configuration for robots"""
    type: WeaponType
    damage: float
    range: float
    fire_rate: float  # seconds between shots
    ammo: int
    max_ammo: int
    reload_time: float
    name: str = ""
    projectile_speed: float = 20.0  # for ranged weapons
    knockback: float = 0.0
    area_effect: float = 0.0  # for explosives

    def __post_init__(self):
        if not self.name:
            self.name = f"{self.type.value}_weapon"


@dataclass
class Robot:
    """Represents an AI-controlled robot in the arena"""
    id: str
    team: Team
    position: Vector2D
    velocity: Vector2D = field(default_factory=lambda: Vector2D(0, 0))
    health: float = 100.0
    max_health: float = 100.0
    armor: float = 0.0
    weapon: Weapon = field(default_factory=lambda: Weapon(
        type=WeaponType.RANGED,
        damage=25.0,
        range=300.0,
        fire_rate=0.5,
        ammo=30,
        max_ammo=60,
        reload_time=2.0,
        name="Plasma Rifle"
    ))
    role: RobotRole = RobotRole.ATTACKER
    cooldown: float = 0.0  # for abilities
    last_action_time: float = 0.0
    target: Optional[str] = None  # ID of target robot or objective
    objectives: List[ObjectiveType] = field(default_factory=list)
    perception: Dict[str, Any] = field(default_factory=dict)  # sensor data
    memory: List[Dict] = field(default_factory=list)  # battle history
    strategy: Dict[str, float] = field(default_factory=dict)  # learned preferences
    is_alive: bool = True
    last_seen_enemies: List[str] = field(default_factory=list)
    team_cooperation_level: float = 0.7  # 0.0 to 1.0, how much they cooperate with team

    def take_damage(self, damage: float, attacker_id: str = None):
        """Apply damage to robot, considering armor"""
        actual_damage = damage * (1 - min(self.armor / 100.0, 0.8))  # cap at 80% reduction
        self.health -= actual_damage
        if self.health <= 0:
            self.health = 0
            self.is_alive = False
        # Record in memory
        if attacker_id:
            self.memory.append({
                "event": "damage_taken",
                "amount": actual_damage,
                "attacker": attacker_id,
                "time": time.time()
            })

    def heal(self, amount: float):
        """Heal the robot"""
        self.health = min(self.max_health, self.health + amount)

    def reload_weapon(self):
        """Reload weapon if ammo is low"""
        if self.weapon.ammo < self.weapon.max_ammo:
            self.weapon.ammo = min(self.weapon.max_ammo, self.weapon.ammo + 10)

    def update(self, delta_time: float):
        """Update robot state"""
        # Update cooldowns
        if self.cooldown > 0:
            self.cooldown -= delta_time
            if self.cooldown < 0:
                self.cooldown = 0

        # Update position based on velocity
        self.position = self.position + (self.velocity * delta_time)

        # Apply friction to velocity
        friction = 0.95
        self.velocity = self.velocity * friction

        # Update perception based on environment (simplified)
        self.perception = {}

    def get_action(self, environment: 'Environment') -> Dict[str, Any]:
        """AI decision-making system - returns action for this robot"""
        # Base behavior: seek objectives, avoid hazards, engage enemies
        action = {
            "move": Vector2D(0, 0),
            "attack": False,
            "ability": None,
            "target": None,
            "role_change": False
        }

        # Get nearby enemies and objectives
        nearby_enemies = []
        nearby_allies = []
        nearby_objectives = []
        nearby_hazards = []
        nearby_powerups = []

        for robot in environment.robots:
            if robot.id == self.id:
                continue
            distance = self.position.distance_to(robot.position)
            if distance < 200:
                if robot.team != self.team and robot.is_alive:
                    nearby_enemies.append((robot, distance))
                elif robot.team == self.team and robot.is_alive:
                    nearby_allies.append((robot, distance))

        for obj in environment.objectives:
            distance = self.position.distance_to(obj.position)
            if distance < 300:
                nearby_objectives.append((obj, distance))

        for hazard in environment.hazards:
            distance = self.position.distance_to(hazard.position)
            if distance < 150:
                nearby_hazards.append((hazard, distance))

        for powerup in environment.powerups:
            distance = self.position.distance_to(powerup.position)
            if distance < 150:
                nearby_powerups.append((powerup, distance))

        # Update perception
        self.perception = {
            "nearby_enemies": nearby_enemies,
            "nearby_allies": nearby_allies,
            "nearby_objectives": nearby_objectives,
            "nearby_hazards": nearby_hazards,
            "nearby_powerups": nearby_powerups,
            "health_ratio": self.health / self.max_health,
            "ammo_ratio": self.weapon.ammo / self.weapon.max_ammo,
            "team_size": len([r for r in environment.robots if r.team == self.team and r.is_alive]),
            "enemy_size": len([r for r in environment.robots if r.team != self.team and r.is_alive])
        }

        # Adaptive AI behavior based on performance and environment
        if self.is_alive:
            action = self._adaptive_decision_making(environment, nearby_enemies, nearby_allies, nearby_objectives, nearby_hazards, nearby_powerups)

        return action

    def _adaptive_decision_making(self, environment, nearby_enemies, nearby_allies, nearby_objectives, nearby_hazards, nearby_powerups):
        """Internal decision-making with adaptive learning"""
        action = {
            "move": Vector2D(0, 0),
            "attack": False,
            "ability": None,
            "target": None,
            "role_change": False
        }

        # Calculate adaptive difficulty scaling
        difficulty_scale = environment.difficulty_level
        learning_factor = 0.3 + (self.strategy.get("win_ratio", 0.5) * 0.4)  # 0.3-0.7 based on win rate

        # Check if we need to change role based on team composition
        if len(nearby_allies) > 0:
            team_roles = defaultdict(int)
            for ally, _ in nearby_allies:
                team_roles[ally.role] += 1

            # If too many attackers, become a defender
            if team_roles[RobotRole.ATTACKER] > 2 and self.role != RobotRole.DEFENDER:
                if random.random() < learning_factor * 0.5:
                    self.role = RobotRole.DEFENDER
                    action["role_change"] = True
            elif team_roles[RobotRole.DEFENDER] > 1 and self.role != RobotRole.ATTACKER:
                if random.random() < learning_factor * 0.4:
                    self.role = RobotRole.ATTACKER
                    action["role_change"] = True

        # Priority 1: If health is low, seek health or retreat
        if self.health < self.max_health * 0.3:
            # Look for health powerups or allies
            health_powerups = [p for p, d in nearby_powerups if p.type == PowerUpType.HEALTH_PACK]
            if health_powerups:
                closest_health = min(health_powerups, key=lambda p: self.position.distance_to(p.position))
                action["move"] = (closest_health.position - self.position).normalize() * 150
                action["target"] = closest_health.id
                return action
            elif len(nearby_allies) > 0:
                # Retreat toward nearest ally
                closest_ally = min(nearby_allies, key=lambda x: x[1])
                action["move"] = (closest_ally[0].position - self.position).normalize() * 80
                return action
            else:
                # Flee from enemies if no allies nearby
                if nearby_enemies:
                    closest_enemy = min(nearby_enemies, key=lambda x: x[1])
                    flee_vector = (self.position - closest_enemy[0].position).normalize() * 100
                    action["move"] = flee_vector
                    return action

        # Priority 2: If we're out of ammo, reload or look for ammo powerup
        if self.weapon.ammo < 5:
            ammo_powerups = [p for p, d in nearby_powerups if p.type == PowerUpType.AMMO_RELOAD]
            if ammo_powerups:
                closest_ammo = min(ammo_powerups, key=lambda p: self.position.distance_to(p.position))
                action["move"] = (closest_ammo.position - self.position).normalize() * 120
                action["target"] = closest_ammo.id
                return action

        # Priority 3: Role-based objectives
        if self.role == RobotRole.ATTACKER:
            # Attack weakest enemy or nearest enemy
            if nearby_enemies:
                # Look for low-health enemies
                low_health_enemies = [e for e, d in nearby_enemies if e.health < 40]
                if low_health_enemies:
                    target_enemy = min(low_health_enemies, key=lambda x: x[1])
                else:
                    target_enemy = min(nearby_enemies, key=lambda x: x[1])

                # Attack if in range
                if target_enemy[1] < self.weapon.range:
                    action["attack"] = True
                    action["target"] = target_enemy[0].id
                    action["move"] = Vector2D(0, 0)  # Stop moving to aim
                else:
                    # Move toward target
                    direction = (target_enemy[0].position - self.position).normalize()
                    action["move"] = direction * 100

        elif self.role == RobotRole.DEFENDER:
            # Protect objectives or base
            if nearby_objectives:
                # Find objectives that belong to our team
                our_objectives = [obj for obj, d in nearby_objectives if obj.team == self.team]
                if our_objectives:
                    closest_obj = min(our_objectives, key=lambda x: self.position.distance_to(x.position))
                    # If enemy is near the objective, defend
                    enemies_near_obj = [
                        e for e, d in nearby_enemies 
                        if e.position.distance_to(closest_obj.position) < 100
                    ]
                    if enemies_near_obj:
                        # Engage threat
                        threat = min(enemies_near_obj, key=lambda x: x[1])
                        action["attack"] = True
                        action["target"] = threat[0].id
                        action["move"] = Vector2D(0, 0)
                    else:
                        # Protect by staying near objective
                        direction = (closest_obj.position - self.position).normalize()
                        action["move"] = direction * 60
                        action["target"] = closest_obj.id
                else:
                    # Default: defend base
                    if environment.base_positions:
                        base_pos = environment.base_positions.get(self.team, Vector2D(0, 0))
                        direction = (base_pos - self.position).normalize()
                        action["move"] = direction * 80
            else:
                # Default: stay near base
                if environment.base_positions:
                    base_pos = environment.base_positions.get(self.team, Vector2D(0, 0))
                    direction = (base_pos - self.position).normalize()
                    action["move"] = direction * 80

        elif self.role == RobotRole.SUPPORT:
            # Heal allies or buff them
            if nearby_allies:
                low_health_allies = [a for a, d in nearby_allies if a.health < a.max_health * 0.5]
                if low_health_allies:
                    target_ally = min(low_health_allies, key=lambda x: x[1])
                    action["move"] = (target_ally[0].position - self.position).normalize() * 80
                    action["target"] = target_ally[0].id
                    # Use ability if available
                    if self.cooldown <= 0 and random.random() < 0.3:
                        action["ability"] = "heal"
                        self.cooldown = 5.0  # 5 second cooldown
                else:
                    # Help with objectives
                    if nearby_objectives:
                        objective = min(nearby_objectives, key=lambda x: x[1])
                        action["move"] = (objective[0].position - self.position).normalize() * 100
                        action["target"] = objective[0].id

        elif self.role == RobotRole.SCOUT:
            # Explore and gather intel
            if nearby_enemies:
                # Engage if advantageous
                if len(nearby_enemies) == 1 and nearby_enemies[0][1] < 150:
                    target_enemy = nearby_enemies[0]
                    action["attack"] = True
                    action["target"] = target_enemy[0].id
                else:
                    # Avoid and report
                    if len(nearby_enemies) > 0:
                        closest_enemy = min(nearby_enemies, key=lambda x: x[1])
                        # Move perpendicular to avoid direct confrontation
                        direction = (closest_enemy[0].position - self.position).normalize()
                        perpendicular = Vector2D(-direction.y, direction.x)
                        action["move"] = perpendicular * 120
                    else:
                        # Scout toward unexplored areas
                        # For simplicity, move toward center of map or random direction
                        center = Vector2D(environment.width / 2, environment.height / 2)
                        direction = (center - self.position).normalize()
                        action["move"] = direction * 100

        # Avoid hazards
        if nearby_hazards:
            closest_hazard = min(nearby_hazards, key=lambda x: x[1])
            if closest_hazard[1] < 50:  # Danger zone
                # Move away from hazard
                avoid_vector = (self.position - closest_hazard[0].position).normalize() * 150
                action["move"] = avoid_vector

        # Pick up powerups if beneficial and not already prioritized
        if nearby_powerups and not action["move"].magnitude() > 80:
            best_powerup = None
            best_priority = 0

            for powerup, distance in nearby_powerups:
                priority = 0
                if powerup.type == PowerUpType.HEALTH_PACK and self.health < 70:
                    priority = 10
                elif powerup.type == PowerUpType.AMMO_RELOAD and self.weapon.ammo < 10:
                    priority = 8
                elif powerup.type == PowerUpType.SPEED_BOOST:
                    priority = 5
                elif powerup.type == PowerUpType.SHIELD and self.armor < 50:
                    priority = 6
                elif powerup.type == PowerUpType.TIME_SLOW:
                    priority = 7

                if priority > best_priority:
                    best_priority = priority
                    best_powerup = powerup

            if best_powerup and best_priority > 0:
                action["move"] = (best_powerup.position - self.position).normalize() * 100
                action["target"] = best_powerup.id

        # Make sure we're not moving into walls (simplified wall avoidance)
        if self.position.x < 50:
            action["move"].x += 50
        elif self.position.x > environment.width - 50:
            action["move"].x -= 50
        if self.position.y < 50:
            action["move"].y += 50
        elif self.position.y > environment.height - 50:
            action["move"].y -= 50

        # Normalize movement vector
        if action["move"].magnitude() > 150:
            action["move"] = action["move"].normalize() * 150

        return action

    def use_ability(self, ability: str, environment: 'Environment'):
        """Use special abilities"""
        if ability == "heal" and self.cooldown <= 0:
            # Heal nearby allies
            for robot in environment.robots:
                if robot.team == self.team and robot.is_alive and robot.id != self.id:
                    dist = self.position.distance_to(robot.position)
                    if dist < 100:
                        robot.heal(20)
            self.cooldown = 5.0  # Cooldown for heal ability


@dataclass
class Objective:
    """Game objective that teams compete for"""
    id: str
    type: ObjectiveType
    team: Team
    position: Vector2D
    captured_by: Optional[Team] = None
    capture_progress: float = 0.0
    capture_rate: float = 0.02  # per second
    radius: float = 30.0
    is_active: bool = True
    required_allies: int = 1  # number of allies needed to capture

    def update(self, environment: 'Environment', delta_time: float):
        """Update capture progress"""
        if not self.is_active:
            return

        # Count allies in capture radius
        allies_nearby = 0
        for robot in environment.robots:
            if robot.team == self.team and robot.is_alive:
                if self.position.distance_to(robot.position) < self.radius:
                    allies_nearby += 1

        # Capture logic
        if allies_nearby >= self.required_allies and self.captured_by != self.team:
            self.capture_progress += self.capture_rate * delta_time
            if self.capture_progress >= 1.0:
                self.captured_by = self.team
                self.capture_progress = 1.0
        elif self.captured_by == self.team and allies_nearby < self.required_allies:
            # If allies leave, progress slowly decreases
            self.capture_progress -= self.capture_rate * 0.5 * delta_time
            if self.capture_progress <= 0:
                self.captured_by = None
                self.capture_progress = 0.0
        elif self.captured_by != self.team and self.captured_by is not None:
            # Enemy has it, try to recapture
            enemies_nearby = 0
            for robot in environment.robots:
                if robot.team != self.team and robot.is_alive:
                    if self.position.distance_to(robot.position) < self.radius:
                        enemies_nearby += 1
            if enemies_nearby >= self.required_allies:
                self.capture_progress -= self.capture_rate * delta_time * 0.3
                if self.capture_progress <= 0:
                    self.captured_by = None
                    self.capture_progress = 0.0


@dataclass
class PowerUp:
    """Power-up items that spawn in the arena"""
    id: str
    type: PowerUpType
    position: Vector2D
    duration: float = 10.0  # seconds
    value: float = 0.0  # amount of effect
    active: bool = True
    spawn_time: float = 0.0

    def apply_effect(self, robot: Robot):
        """Apply the power-up effect to a robot"""
        if self.type == PowerUpType.HEALTH_PACK:
            robot.heal(self.value)
        elif self.type == PowerUpType.AMMO_RELOAD:
            robot.weapon.ammo = robot.weapon.max_ammo
        elif self.type == PowerUpType.SPEED_BOOST:
            # Temporary speed boost
            robot.speed_multiplier = getattr(robot, 'speed_multiplier', 1.0)
            robot.speed_multiplier = min(robot.speed_multiplier * 1.5, 2.0)
            # Reset after duration
            threading.Timer(self.duration, lambda: setattr(robot, 'speed_multiplier', 1.0)).start()
        elif self.type == PowerUpType.SHIELD:
            robot.armor = min(robot.armor + self.value, 100.0)
        elif self.type == PowerUpType.TELEPORT:
            # Teleport to a random location
            robot.position = Vector2D(
                random.uniform(100, 700),
                random.uniform(100, 500)
            )
        elif self.type == PowerUpType.TIME_SLOW:
            # Slow down enemy movement for a duration
            environment = getattr(self, 'environment', None)
            if environment:
                for robot in environment.robots:
                    if robot.team != robot.team:  # This line is wrong, should be robot.team != self.team
                        robot.slowed = True
                        threading.Timer(self.duration, lambda: setattr(robot, 'slowed', False)).start()


@dataclass
class Hazard:
    """Environmental hazards that damage robots"""
    id: str
    type: HazardType
    position: Vector2D
    damage_per_second: float
    radius: float
    active: bool = True

    def affect_robot(self, robot: Robot):
        """Apply damage to robot if in range"""
        if not self.active:
            return

        distance = self.position.distance_to(robot.position)
        if distance < self.radius:
            robot.take_damage(self.damage_per_second * 0.1)  # Damage over time
            # Push robot away from hazard
            if distance > 0:
                push_direction = (robot.position - self.position).normalize()
                robot.velocity += push_direction * 50.0


@dataclass
class Environment:
    """The game world and state"""
    width: int = 800
    height: int = 600
    robots: List[Robot] = field(default_factory=list)
    objectives: List[Objective] = field(default_factory=list)
    powerups: List[PowerUp] = field(default_factory=list)
    hazards: List[Hazard] = field(default_factory=list)
    base_positions: Dict[Team, Vector2D] = field(default_factory=dict)
    difficulty_level: float = 0.5  # 0.0 to 1.0
    time_elapsed: float = 0.0
    team_scores: Dict[Team, int] = field(default_factory=lambda: {Team.RED: 0, Team.BLUE: 0})
    last_spawn_time: float = 0.0
    spawn_cooldown: float = 15.0
    game_state: str = "active"  # active, paused, finished

    def __post_init__(self):
        # Set default base positions
        self.base_positions = {
            Team.RED: Vector2D(100, 300),
            Team.BLUE: Vector2D(700, 300)
        }

        # Initialize objectives based on game mode
        self.objectives = [
            Objective("flag_red", ObjectiveType.FLAG_CAPTURE, Team.RED, Vector2D(150, 200)),
            Objective("flag_blue", ObjectiveType.FLAG_CAPTURE, Team.BLUE, Vector2D(650, 200)),
            Objective("control_center", ObjectiveType.CONTROL_POINT, Team.RED, Vector2D(400, 300))
        ]

        # Initialize hazards
        self.hazards = [
            Hazard("lava1", HazardType.LAVA, Vector2D(400, 100), 5.0, 40),
            Hazard("electric1", HazardType.ELECTRIC_FIELD, Vector2D(200, 400), 3.0, 30),
            Hazard("minefield1", HazardType.MINEFIELD, Vector2D(600, 450), 2.0, 50),
        ]

        # Initialize powerups
        self.powerups = [
            PowerUp("health1", PowerUpType.HEALTH_PACK, Vector2D(300, 150), 30.0, 40.0),
            PowerUp("ammo1", PowerUpType.AMMO_RELOAD, Vector2D(500, 150), 30.0, 0.0),
            PowerUp("shield1", PowerUpType.SHIELD, Vector2D(350, 450), 30.0, 30.0),
            PowerUp("speed1", PowerUpType.SPEED_BOOST, Vector2D(450, 450), 20.0, 0.0),
        ]

    def create_robot(self, team: Team, role: RobotRole = RobotRole.ATTACKER) -> Robot:
        """Create a new robot with random position in team base area"""
        base_pos = self.base_positions[team]
        x_offset = random.uniform(-50, 50)
        y_offset = random.uniform(-50, 50)

        position = Vector2D(base_pos.x + x_offset, base_pos.y + y_offset)

        # Select weapon based on role
        weapons = {
            RobotRole.ATTACKER: Weapon(
                type=WeaponType.RANGED,
                damage=25,
                range=300,
                fire_rate=0.5,
                ammo=30,
                max_ammo=60,
                reload_time=2.0,
                name="Plasma Rifle"
            ),
            RobotRole.DEFENDER: Weapon(
                type=WeaponType.MELEE,
                damage=45,
                range=80,
                fire_rate=1.5,
                ammo=1,
                max_ammo=1,
                reload_time=0.5,
                name="Plasma Sword",
                knockback=50.0
            ),
            RobotRole.SUPPORT: Weapon(
                type=WeaponType.RANGED,
                damage=15,
                range=250,
                fire_rate=0.3,
                ammo=40,
                max_ammo=80,
                reload_time=1.5,
                name="Medi-Pulse"
            ),
            RobotRole.SCOUT: Weapon(
                type=WeaponType.RANGED,
                damage=20,
                range=200,
                fire_rate=0.6,
                ammo=35,
                max_ammo=70,
                reload_time=1.8,
                name="Sniper Rifle"
            )
        }

        robot = Robot(
            id=f"robot_{len(self.robots)}_{team.value}",
            team=team,
            position=position,
            role=role,
            weapon=weapons[role],
            strategy={"win_ratio": 0.5, "cooperation": 0.7}
        )
        self.robots.append(robot)
        return robot

    def update(self, delta_time: float):
        """Update the entire environment"""
        self.time_elapsed += delta_time

        # Spawn new robots if team is too small
        red_count = len([r for r in self.robots if r.team == Team.RED and r.is_alive])
        blue_count = len([r for r in self.robots if r.team == Team.BLUE and r.is_alive])

        # Adaptive difficulty: spawn more robots if one team is dominating
        if red_count == 0 and blue_count > 0 and self.time_elapsed - self.last_spawn_time > self.spawn_cooldown:
            self.create_robot(Team.RED, RobotRole.ATTACKER)
            self.last_spawn_time = self.time_elapsed
        elif blue_count == 0 and red_count > 0 and self.time_elapsed - self.last_spawn_time > self.spawn_cooldown:
            self.create_robot(Team.BLUE, RobotRole.ATTACKER)
            self.last_spawn_time = self.time_elapsed
        elif red_count < 2 and blue_count > 0 and self.time_elapsed - self.last_spawn_time > self.spawn_cooldown * 3:
            self.create_robot(Team.RED, RobotRole.SUPPORT)
            self.last_spawn_time = self.time_elapsed
        elif blue_count < 2 and red_count > 0 and self.time_elapsed - self.last_spawn_time > self.spawn_cooldown * 3:
            self.create_robot(Team.BLUE, RobotRole.SUPPORT)
            self.last_spawn_time = self.time_elapsed

        # Update robots
        for robot in self.robots:
            if robot.is_alive:
                robot.update(delta_time)

                # Get robot's action
                action = robot.get_action(self)

                # Apply movement
                robot.velocity = action["move"]

                # Apply attack
                if action["attack"]:
                    target_robot = None
                    for r in self.robots:
                        if r.id == action["target"] and r.is_alive:
                            target_robot = r
                            break

                    if target_robot:
                        distance = robot.position.distance_to(target_robot.position)
                        if distance <= robot.weapon.range:
                            # Apply damage
                            target_robot.take_damage(robot.weapon.damage, robot.id)

                            # Apply knockback
                            if robot.weapon.knockback > 0:
                                direction = (target_robot.position - robot.position).normalize()
                                target_robot.velocity += direction * robot.weapon.knockback

                            # Reduce ammo
                            robot.weapon.ammo -= 1
                            if robot.weapon.ammo <= 0:
                                robot.weapon.ammo = 0
                                # Try to reload
                                if self.time_elapsed - robot.last_action_time > robot.weapon.reload_time:
                                    robot.reload_weapon()

                # Apply ability
                if action["ability"] == "heal":
                    robot.use_ability("heal", self)

        # Update objectives
        for obj in self.objectives:
            obj.update(self, delta_time)

            # Check if objective is captured for scoring
            if obj.captured_by and obj.captured_by != obj.team:
                # Objective changed hands
                self.team_scores[obj.captured_by] += 10
                obj.team = obj.captured_by  # Change ownership

        # Update hazards
        for hazard in self.hazards:
            if hazard.active:
                for robot in self.robots:
                    if robot.is_alive:
                        hazard.affect_robot(robot)

        # Update powerups
        for powerup in self.powerups:
            if powerup.active:
                # Check if any robot is near powerup
                for robot in self.robots:
                    if robot.is_alive and powerup.position.distance_to(robot.position) < 40:
                        powerup.apply_effect(robot)
                        powerup.active = False
                        # Spawn a new one after delay
                        threading.Timer(30, self._respawn_powerup, args=[powerup]).start()

        # Update difficulty based on performance
        self._update_difficulty()

        # Check game end conditions
        self._check_game_end()

    def _respawn_powerup(self, original_powerup: PowerUp):
        """Respawn a powerup after it's been collected"""
        new_powerup = PowerUp(
            id=f"{original_powerup.id}_respawn_{int(time.time())}",
            type=original_powerup.type,
            position=Vector2D(
                random.uniform(100, self.width - 100),
                random.uniform(100, self.height - 100)
            ),
            duration=original_powerup.duration,
            value=original_powerup.value,
            active=True,
            spawn_time=time.time()
        )
        self.powerups.append(new_powerup)

    def _update_difficulty(self):
        """Adapt difficulty based on team balance and performance"""
        red_alive = len([r for r in self.robots if r.team == Team.RED and r.is_alive])
        blue_alive = len([r for r in self.robots if r.team == Team.BLUE and r.is_alive])

        # Adjust difficulty based on team size ratio
        total_alive = red_alive + blue_alive
        if total_alive > 0:
            ratio = max(red_alive, blue_alive) / total_alive
            if ratio > 0.7:  # One team is dominating
                self.difficulty_level = min(1.0, self.difficulty_level + 0.02)
            elif ratio < 0.3:  # Opposing team is dominant
                self.difficulty_level = max(0.1, self.difficulty_level - 0.02)
            else:
                # Balance difficulty
                self.difficulty_level = 0.5 + (self.difficulty_level - 0.5) * 0.98  # Dampen changes

        # Adjust AI strategy learning rate based on difficulty
        for robot in self.robots:
            if robot.is_alive:
                # Higher difficulty = more aggressive AI
                aggression_factor = self.difficulty_level
                robot.strategy["win_ratio"] = max(0.1, min(0.9, robot.strategy.get("win_ratio", 0.5) + (aggression_factor - 0.5) * 0.05))
                robot.team_cooperation_level = 0.6 + (aggression_factor * 0.3)  # 0.6 to 0.9

    def _check_game_end(self):
        """Check if game should end"""
        red_alive = len([r for r in self.robots if r.team == Team.RED and r.is_alive])
        blue_alive = len([r for r in self.robots if r.team == Team.BLUE and r.is_alive])

        if red_alive == 0 or blue_alive == 0:
            self.game_state = "finished"
            self._determine_winner()

    def _determine_winner(self):
        """Determine winner based on scores and alive robots"""
        if self.team_scores[Team.RED] > self.team_scores[Team.BLUE]:
            print("RED TEAM WINS!")
        elif self.team_scores[Team.BLUE] > self.team_scores[Team.RED]:
            print("BLUE TEAM WINS!")
        else:
            # Tie breaker: most robots alive
            red_alive = len([r for r in self.robots if r.team == Team.RED and r.is_alive])
            blue_alive = len([r for r in self.robots if r.team == Team.BLUE and r.is_alive])
            if red_alive > blue_alive:
                print("RED TEAM WINS BY ALIVE ROBOTS!")
            elif blue_alive > red_alive:
                print("BLUE TEAM WINS BY ALIVE ROBOTS!")
            else:
                print("IT'S A TIE!")


