def update(self, robots: List[Robot], objectives: List[Objective], delta_time: float):
        current_time = time.time()
        if current_time - self.last_update_time < 0.1:  # Limit updates to 10 FPS for performance
            return
        self.last_update_time = current_time

        # Update kills and deaths
        for robot in robots:
            if not robot.is_alive and robot.memory.get('last_killer'):
                killer_team = None
                for r in robots:
                    if r.id == robot.memory['last_killer']:
                        killer_team = r.team
                        break
                if killer_team:
                    self.kills[killer_team] += 1
                    self.deaths[robot.team] += 1

        # Update objective completions and assign team scores
        for obj in objectives:
            if obj.is_captured and obj.capture_team and obj.capture_team != obj.last_captured_team:
                self.objectives_completed[obj.capture_team] += 1
                self.team_scores[obj.capture_team] += 50  # Base score for capturing
                obj.last_captured_team = obj.capture_team

        # Calculate teamwork bonuses: assist kills, shared objective capture
        for robot in robots:
            if robot.team_role == "support" and robot.memory.get('healed_recently'):
                self.teamwork_bonus[robot.team] += 0.5  # Bonus for healing allies

            if robot.objective_progress >= 1.0:
                self.teamwork_bonus[robot.team] += 0.2  # Bonus for contributing to objective

        # Apply teamwork bonus to team scores (capped at 20% of base score)
        for team in Team:
            self.team_scores[team] += min(self.teamwork_bonus[team], self.team_scores[team] * 0.2)
            self.teamwork_bonus[team] *= 0.95  # Decay bonus over time

        # Award points for kills
        for team in Team:
            self.team_scores[team] += self.kills[team] * 10

        # Ensure scores don't go negative
        for team in Team:
